using namespace std;

int main() {
    int n;
    cin >> n;
    const int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};
    for (int i = 0; i < n; i++) {
        string cmd;
        cin >> cmd;
        int x = 0, y = 0, dir = 0;
        for (char c : cmd) {
            if (c == 'G') { x += dx[dir]; y += dy[dir]; }
            else if (c == 'L') dir = (dir + 3) % 4;
            else dir = (dir + 1) % 4;
        }
        // Bounded iff back at the origin or facing a different direction after one pass.
        puts((x == 0 && y == 0) || dir != 0 ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int[] dx = {0, 1, 0, -1}, dy = {1, 0, -1, 0};
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            while (!st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            String cmd = st.nextToken();
            int x = 0, y = 0, dir = 0;
            for (int j = 0; j < cmd.length(); j++) {
                char c = cmd.charAt(j);
                if (c == 'G') { x += dx[dir]; y += dy[dir]; }
                else if (c == 'L') dir = (dir + 3) % 4;
                else dir = (dir + 1) % 4;
            }
            // Bounded iff back at the origin or facing a different direction after one pass.
            out.append((x == 0 && y == 0) || dir != 0 ? "YES" : "NO").append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	dx, dy := []int{0, 1, 0, -1}, []int{1, 0, -1, 0}
	for i := 0; i < n; i++ {
		var cmd string
		fmt.Fscan(in, &cmd)
		x, y, dir := 0, 0, 0
		for _, c := range cmd {
			switch c {
			case 'G':
				x += dx[dir]
				y += dy[dir]
			case 'L':
				dir = (dir + 3) % 4
			default:
				dir = (dir + 1) % 4
			}
		}
		// Bounded iff back at the origin or facing a different direction after one pass.
		if (x == 0 && y == 0) || dir != 0 {
			fmt.Println("YES")
		} else {
			fmt.Println("NO")
		}
	}
}
